fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let n = v.len();
    debug_assert!(n > 0);

    // Search interval is [lo, hi), and we maintain that k occurs somewhere in it.
    let mut lo: usize = 0;
    let mut hi: usize = n;

    while hi - lo > 1 {
        let mid = lo + (hi - lo) / 2;

        if v[mid] <= k {
            // k occurs in [mid, hi) if it occurs in [lo, hi)
            lo = mid;
        } else {
            // v[mid] > k, so k (if present) must be in [lo, mid)
            hi = mid;
        }
    }

    // With the assumptions (sorted, non-empty, k present), this must hold.
    debug_assert!(lo < n && v[lo] == k);
    lo
}